# -*- coding: utf-8 -*-
# Catechism bank — the Iẓhār Q&A, bāb 2 (the governed word), items 51–73.
ITEMS = [
 {"n": 51, "q": {"tr": "إِلَّا ne zaman sıfat olan غَيْر üzerine hamledilir? Misali nedir?", "en": "When is إِلَّا carried over to the adjectival غَيْر, and what is the example?"},
  "a": {"tr": "İstisnâ mazur olduğu (mânâ fâsid olduğu) zaman إِلَّا sıfat olmakta غَيْر üzerine hamlolunur: لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللهُ لَفَسَدَتَا âyetinde olduğu gibi; burada mânâ fâsid olduğundan istisnâ mazur görülmüş ve إِلَّا sıfat olmakta غَيْر mânâsında kullanılmıştır.", "en": "When the exception is excused — the sense would be corrupt — إِلَّا is read as the adjective غَيْر: as in لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللهُ لَفَسَدَتَا, where an exception would corrupt the meaning, so إِلَّا stands for غَيْر."},
  "ar": ["لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللهُ لَفَسَدَتَا"], "notes": ["al-mustathna-badaluhu-wa-jarruh-wa-ghayr-wa-illa"]},
 {"n": 52, "q": {"tr": "كَانَ bâbının haberinin âmilini hazfetmek câiz midir?", "en": "May the governor of the khabar of كَانَ be dropped?"},
  "a": {"tr": "Câizdir: النَّاسُ مَجْزِيُّونَ بِأَعْمَالِهِمْ إِنْ خَيْرًا فَخَيْرٌ وَإِنْ شَرًّا فَشَرٌّ. Burada dört vecih vardır: إِنْ خَيْرًا فَخَيْرٌ (takdiri إِنْ كَانَ عَمَلُهُ خَيْرًا فَجَزَاؤُهُ خَيْرٌ); إِنْ خَيْرًا فَخَيْرًا (فَكَانَ جَزَاؤُهُ خَيْرًا); إِنْ خَيْرٌ فَخَيْرٌ (إِنْ كَانَ فِي عَمَلِهِ خَيْرٌ فَجَزَاؤُهُ خَيْرٌ); إِنْ خَيْرٌ فَخَيْرًا (فَكَانَ جَزَاؤُهُ خَيْرًا).", "en": "Yes: النَّاسُ مَجْزِيُّونَ بِأَعْمَالِهِمْ إِنْ خَيْرًا فَخَيْرٌ وَإِنْ شَرًّا فَشَرٌّ, with four readings: إِنْ خَيْرًا فَخَيْرٌ (إِنْ كَانَ عَمَلُهُ خَيْرًا فَجَزَاؤُهُ خَيْرٌ); إِنْ خَيْرًا فَخَيْرًا (فَكَانَ جَزَاؤُهُ خَيْرًا); إِنْ خَيْرٌ فَخَيْرٌ (إِنْ كَانَ فِي عَمَلِهِ خَيْرٌ فَجَزَاؤُهُ خَيْرٌ); إِنْ خَيْرٌ فَخَيْرًا (فَكَانَ جَزَاؤُهُ خَيْرًا)."},
  "ar": ["النَّاسُ مَجْزِيُّونَ بِأَعْمَالِهِمْ إِنْ خَيْرًا فَخَيْرٌ وَإِنْ شَرًّا فَشَرٌّ"], "notes": ["al-mansubat-al-tasi-ila-al-thalith-ashar"]},
 {"n": 53, "q": {"tr": "كَانَ bâbının haberinin hükmü ne gibidir?", "en": "What is the ruling of the khabar of كَانَ like?"},
  "a": {"tr": "Nekre olmakta, taaddüdünün câiz olmasında, cümle olmakta, mezkûr ve mahzûf olmakta mübtedânın haberi gibidir.", "en": "Like the khabar of the mubtadaʾ: indefinite, multipliable, a sentence, stated or dropped."},
  "ar": ["خَبَرُ كَانَ"], "notes": ["al-mansubat-al-tasi-ila-al-thalith-ashar", "kana-wa-akhawatuha"]},
 {"n": 54, "q": {"tr": "إِنَّ bâbının isminin hükmü ne gibidir?", "en": "What is the ruling of the ism of إِنَّ like?"},
  "a": {"tr": "İsim veya isim te'vîlinde olmakta, atıf harfi olmaksızın taaddüdünün câiz olmamasında, ma'rife veya hususîleşmiş nekre olmakta mübtedâ gibidir; ancak إِنَّ bâbının ismini hazfetmek câiz değildir.", "en": "Like the mubtadaʾ: a noun or construed as one; not multiplied without a conjunction; definite or an indefinite made particular — but it may not be dropped."},
  "ar": ["اسْمُ إِنَّ"], "notes": ["al-mansubat-al-tasi-ila-al-thalith-ashar", "inna-wa-akhawatuha"]},
 {"n": 55, "q": {"tr": "لَيْسَ'ye benzeyen مَا ve لَا'nın haberinin hükmü ne gibidir?", "en": "What is the ruling of the khabar of مَا and لَا like لَيْسَ?"},
  "a": {"tr": "Nekre olmakta, taaddüdünün câiz olmasında, cümle olmakta, mezkûr ve mahzûf olmakta mübtedânın haberi gibidir.", "en": "Like the khabar of the mubtadaʾ: indefinite, multipliable, a sentence, stated or dropped."},
  "ar": ["خَبَرُ مَا وَلَا الْمُشَبَّهَتَيْنِ بِلَيْسَ"], "notes": ["al-mansubat-al-tasi-ila-al-thalith-ashar", "ma-la-mushabbaha"]},
 {"n": 56, "q": {"tr": "Ma'mûl-i mecrûr kaçtır? Muzâfun ileyhin muzâf üzerine takdimi câiz midir?", "en": "How many majrūr governed words are there, and may the annexed-to precede the annexed?"},
  "a": {"tr": "İki: harf-i cer ile mecrûr ve izâfet ile mecrûr. Muzâfun ileyhin de, muzâfun ileyhin ma'mûlünün de muzâf üzerine takdimi câiz değildir; ancak muzâf غَيْر lafzı olursa ma'mûlünün takdimi câizdir (أَنَا زَيْدًا غَيْرُ ضَارِبٍ, aslı أَنَا غَيْرُ ضَارِبٍ زَيْدًا).", "en": "Two: by a jarr letter and by annexation. Neither the annexed-to nor its dependent may precede the annexed — unless the annexed is غَيْر, when its dependent may (أَنَا زَيْدًا غَيْرُ ضَارِبٍ, from أَنَا غَيْرُ ضَارِبٍ زَيْدًا)."},
  "ar": ["أَنَا زَيْدًا غَيْرُ ضَارِبٍ"], "notes": ["al-majrur-bil-harf-wa-bil-idafa"]},
 {"n": 57, "q": {"tr": "Muzâfın hazfi câiz midir?", "en": "May the annexed noun be dropped?"},
  "a": {"tr": "Bazen muzâf hazfolunur ve i'rabı muzâfun ileyhe verilir (وَاسْأَلِ الْقَرْيَةَ, aslı وَاسْأَلْ أَهْلَ الْقَرْيَةِ). Nadiren mecrûr, mecrûr olarak kalır (يُرِيدُ الْآخِرَةَ — bazı kıraatte الْآخِرَةِ — aslı ثَوَابَ الْآخِرَةِ).", "en": "Sometimes, and its iʿrāb passes to the annexed-to (وَاسْأَلِ الْقَرْيَةَ, from وَاسْأَلْ أَهْلَ الْقَرْيَةِ). Rarely the majrūr stays majrūr (يُرِيدُ الْآخِرَةِ in one reading, from ثَوَابَ الْآخِرَةِ)."},
  "ar": ["وَاسْأَلِ الْقَرْيَةَ"], "notes": ["hadhf-al-mudaf-wal-mudaf-ilayh"]},
 {"n": 58, "q": {"tr": "Muzâfun ileyhin hazfi câiz midir?", "en": "May the annexed-to be dropped?"},
  "a": {"tr": "Bazen hazfolunur. Hazfolunanın mislinde muzâf olan isim muzâf üzerine atfolunursa (بَيْنَ ذِرَاعَيْ وَجَبْهَةِ الْأَسَدِ, aslı بَيْنَ ذِرَاعَيِ الْأَسَدِ وَجَبْهَةِ الْأَسَدِ) veya tekrar ederse (يَا تَيْمَ تَيْمَ عَدِيٍّ) muzâf hâli üzere kalır. Bu iki hâl olmazsa muzâf gaye olmadıkça muzâfun ileyhten bedel olarak tenvinlenir (كُلًّا آتَيْنَاهُ، حِينَئِذٍ، يَوْمَئِذٍ); gaye ise zamme üzere mebnî kılınır (أَمَّا بَعْدُ).", "en": "Sometimes. When a noun annexed to the like of the dropped word is joined to the annexed (بَيْنَ ذِرَاعَيْ وَجَبْهَةِ الْأَسَدِ, from بَيْنَ ذِرَاعَيِ الْأَسَدِ وَجَبْهَةِ الْأَسَدِ) or repeats it (يَا تَيْمَ تَيْمَ عَدِيٍّ), the annexed stays as it was. Otherwise it takes a tanwīn in place of the annexed-to unless it is a limit-word (كُلًّا آتَيْنَاهُ، حِينَئِذٍ، يَوْمَئِذٍ); a limit-word is built on ḍamma (أَمَّا بَعْدُ)."},
  "ar": ["يَا تَيْمَ تَيْمَ عَدِيٍّ", "أَمَّا بَعْدُ"], "notes": ["hadhf-al-mudaf-wal-mudaf-ilayh"]},
 {"n": 59, "q": {"tr": "Ma'mûl-i meczûm kaçtır? Fiil-i muzâride cezm ne zaman vâcib, ne zaman câiz olur?", "en": "How many majzūm governed words are there, and when is the jazm of the muḍāriʿ obligatory or optional?"},
  "a": {"tr": "Birdir: cevâzimden biri kendisine dâhil olan fiil-i muzâri. Şart ve cezâ her ikisi veya biri fâsız muzâri olursa cezm vâcibdir (إِنْ تَضْرِبْ أَضْرِبْ). Şart mâzî, cezâ fâsız muzâri olursa cezâda cezm de ref' de câizdir (إِنْ أَتَانِي آتِهِ / آتِيهِ).", "en": "One: the muḍāriʿ under a jāzim. When both or either of the condition and its answer is a fāʾ-less muḍāriʿ, the jazm is obligatory (إِنْ تَضْرِبْ أَضْرِبْ). When the condition is a māḍī and the answer a fāʾ-less muḍāriʿ, the answer may take jazm or rafʿ (إِنْ أَتَانِي آتِهِ / آتِيهِ)."},
  "ar": ["إِنْ تَضْرِبْ أَضْرِبْ"], "notes": ["al-majzum-wal-shart-wal-jaza", "in-shartiyya"]},
 {"n": 60, "q": {"tr": "Cezâya fânın dühûlü kaç kısımdır?", "en": "How many kinds has the entry of the fāʾ into the answer of a condition?"},
  "a": {"tr": "Üç: mümteni', vâcib, câiz. Cezâ muzâri mânâsına mutasarrıf mâzî veya لَمْ، لَمَّا ile menfî muzâri olursa fâ mümteni'dir. Beş yerde vâcibdir: cezâ cümle-i ismiyye, gayr-i mutasarrıf mâzî, kendi mânâsına mâzî, س، سَوْفَ، لَنْ، مَا'dan birine yakın muzâri veya cümle-i fiiliyye-i inşâiyye olursa. Cezâ bunlara yakın olmayıp müsbet veya لَا ile menfî muzâri olursa fânın dühûlü de hazfi de câizdir.", "en": "Three: forbidden, obligatory, allowed. Forbidden when the answer is a conjugating māḍī in the sense of a muḍāriʿ, or a muḍāriʿ negated by لَمْ، لَمَّا. Obligatory in five: a nominal sentence; a non-conjugating māḍī; a māḍī in its own sense; a muḍāriʿ with س، سَوْفَ، لَنْ، مَا; a performative verbal sentence. Allowed either way when the answer is an affirmative muḍāriʿ or one negated by لَا, without those particles."},
  "ar": ["الْفَاءُ فِي جَوَابِ الشَّرْطِ"], "notes": ["al-fa-fi-jawab-al-shart"]},
 {"n": 61, "q": {"tr": "Ma'mûl bi't-tebaiyye kaçtır?", "en": "How many words are governed by following?"},
  "a": {"tr": "Beştir: sıfat, atıf, te'kid, bedel, atf-ı beyan.", "en": "Five: the adjective, the conjunction, the emphasis, the substitute and the explicative apposition."},
  "ar": ["الْمَعْمُولُ بِالتَّبَعِيَّةِ خَمْسَةٌ"], "notes": ["al-tawabi-wal-sifa"]},
 {"n": 62, "q": {"tr": "Sıfat nedir? Cümle-i haberiyye ile ne vasıflanır?", "en": "What is the adjective, and what is described by a declarative sentence?"},
  "a": {"tr": "Sıfat: mutlak olarak metbûunda bir mânâya delâlet eden tâbidir. Nekre cümle-i haberiyye ile vasıflanır ve cümlede nekreye râci bir zamir lâzım gelir (جَاءَنِي رَجُلٌ أَبُوهُ قَائِمٌ).", "en": "A follower that indicates a meaning in its antecedent, absolutely. An indefinite noun is described by a declarative sentence, which must hold a pronoun returning to it (جَاءَنِي رَجُلٌ أَبُوهُ قَائِمٌ)."},
  "ar": ["تَابِعٌ يَدُلُّ عَلَى مَعْنًى فِي مَتْبُوعِهِ مُطْلَقًا", "جَاءَنِي رَجُلٌ أَبُوهُ قَائِمٌ"], "notes": ["al-tawabi-wal-sifa", "naat-sifa", "jumla-sifa"]},
 {"n": 63, "q": {"tr": "Mevsûfun hâli ile sıfat vâki olduğu zaman, sıfat mevsûfa kaç yerde mutâbakat eder?", "en": "When the adjective describes the noun's own state, in how many things does it agree with it?"},
  "a": {"tr": "On yerde: i'rab (ref', nasb, cer), ma'rife, nekre, müfred, tesniye, cem', müzekker ve müennes (جَاءَنِي رَجُلٌ عَالِمٌ).", "en": "Ten: the iʿrāb (rafʿ, naṣb, jarr), definite, indefinite, singular, dual, plural, masculine and feminine (جَاءَنِي رَجُلٌ عَالِمٌ)."},
  "ar": ["جَاءَنِي رَجُلٌ عَالِمٌ"], "notes": ["al-tawabi-wal-sifa", "naat-sifa"]},
 {"n": 64, "q": {"tr": "Ne zaman mevsûfun müteallakının hâli ile sıfat vâki olur? Bu durumda sıfat mevsûfa kaç yerde mutâbakat eder?", "en": "When does the adjective describe the state of something attached to the noun, and how far does it then agree?"},
  "a": {"tr": "Sıfat, sarfî sıfat olup zâhirî fâilinde amel ettiği zaman mevsûfun müteallakının hâli ile vasıflanır (جَاءَنِي رَجُلٌ رَاكِبٌ غُلَامُهُمْ). Bu durumda sıfat ilk beş yerde (ref', nasb, cer, ma'rife, nekre) mevsûfa mutâbakat eder; kalan yerlerde (müfred, tesniye, cem', müzekker, müennes) sıfat fiil gibidir.", "en": "When the adjective is a derived adjective governing an overt doer (جَاءَنِي رَجُلٌ رَاكِبٌ غُلَامُهُمْ). It then agrees in the first five — rafʿ, naṣb, jarr, definite, indefinite — and in the rest (singular, dual, plural, masculine, feminine) behaves like a verb."},
  "ar": ["جَاءَنِي رَجُلٌ رَاكِبٌ غُلَامُهُمْ"], "notes": ["al-tawabi-wal-sifa"]},
 {"n": 65, "q": {"tr": "Ma'rife ve nekre nedir?", "en": "What are the definite and the indefinite?"},
  "a": {"tr": "Ma'rife: muayyen bir şey için vaz olunandır. Nekre: muayyen olmayan bir şey için vaz olunandır.", "en": "The definite is what is coined for a particular thing; the indefinite for a thing not particular."},
  "ar": ["مَا وُضِعَ لِشَيْءٍ بِعَيْنِهِ", "مَا وُضِعَ لِشَيْءٍ لَا بِعَيْنِهِ"], "notes": ["al-marifa-al-mudmarat-wal-alam", "al-marifa-wal-nakira-fil-kafiya"]},
 {"n": 66, "q": {"tr": "Ma'rife kaç nevidir?", "en": "How many kinds of definite noun are there?"},
  "a": {"tr": "Altı: zamirler, alem, ism-i işâretler, ism-i mevsûl, lâm-ı ta'rif ve nidâ harfi ile ma'rife olan, bu beş şeyden birine izâfet-i mâneviyye ile ma'rife olan.", "en": "Six: the pronouns, the proper name, the demonstratives, the relative, what is made definite by the article or by the particle of calling, and what is made definite by annexation of meaning to one of those five."},
  "ar": ["الْمَعْرِفَةُ سِتَّةُ أَنْوَاعٍ"], "notes": ["al-marifa-al-mudmarat-wal-alam"]},
 {"n": 67, "q": {"tr": "Zamirler kaç kısımdır?", "en": "How many kinds of pronoun are there?"},
  "a": {"tr": "Dört: merfû muttasıl (ضَرَبْتُ … ضَرَبْنَ), merfû munfasıl (أَنَا … هُنَّ), mansub muttasıl ile mecrûr muttasıl arasında müşterek olanlar (ضَرَبَنِي … ضَرَبَهُنَّ؛ لِي … لَهُنَّ), mansub munfasıl (إِيَّايَ … إِيَّاهُنَّ).", "en": "Four: attached marfūʿ (ضَرَبْتُ … ضَرَبْنَ), detached marfūʿ (أَنَا … هُنَّ), those shared between attached manṣūb and attached majrūr (ضَرَبَنِي … ضَرَبَهُنَّ؛ لِي … لَهُنَّ), and detached manṣūb (إِيَّايَ … إِيَّاهُنَّ)."},
  "ar": ["الْمُضْمَرَاتُ أَرْبَعَةُ أَقْسَامٍ"], "notes": ["al-marifa-al-mudmarat-wal-alam"]},
 {"n": 68, "q": {"tr": "İsm-i işâretler nelerdir?", "en": "Which are the demonstratives?"},
  "a": {"tr": "Müzekkerin müfredi için ذَا, tesniyesi için ذَانِ، ذَيْنِ; müennesin müfredi için تَا، ذِي، تِي، تِهِ، ذِهِ، تِهِي، ذِهِي, tesniyesi için تَانِ، تَيْنِ; her ikisinin cem'i için أُولَاءِ. Uzaklık için تِلْكَ، أُولَئِكَ، ذَانِكَ، تَانِكَ; mekân için ثَمَّ، هُنَا، هَهُنَا، هُنَاكَ، هُنَالِكَ.", "en": "For the masculine singular ذَا, dual ذَانِ، ذَيْنِ; feminine singular تَا، ذِي، تِي، تِهِ، ذِهِ، تِهِي، ذِهِي, dual تَانِ، تَيْنِ; plural of both أُولَاءِ. For distance تِلْكَ، أُولَئِكَ، ذَانِكَ، تَانِكَ; for place ثَمَّ، هُنَا، هَهُنَا، هُنَاكَ، هُنَالِكَ."},
  "ar": ["أَسْمَاءُ الْإِشَارَةِ"], "notes": ["asma-al-ishara-wa-sighuha", "asma-al-ishara"]},
 {"n": 69, "q": {"tr": "İsm-i mevsûller nelerdir?", "en": "Which are the relatives?"},
  "a": {"tr": "Müzekkerin müfredi için الَّذِي, tesniyesi için اللَّذَانِ، اللَّذَيْنِ, cem'i için الَّذِينَ; müennesin müfredi için الَّتِي, tesniyesi için اللَّتَانِ، اللَّتَيْنِ, cem'i için اللَّوَاتِي، اللَّائِي، اللَّاتِي، اللَّاتِ; istifham مَا'sından sonraki ذَا; مَنْ، مَا، أَيّ، أَيَّة; ism-i fâil ve ism-i mef'ûldeki الَّذِي ve الَّتِي mânâsına olan elif-lâm.", "en": "Masculine singular الَّذِي, dual اللَّذَانِ، اللَّذَيْنِ, plural الَّذِينَ; feminine singular الَّتِي, dual اللَّتَانِ، اللَّتَيْنِ, plural اللَّوَاتِي، اللَّائِي، اللَّاتِي، اللَّاتِ; ذَا after the question-مَا; مَنْ، مَا، أَيّ، أَيَّة; and the alif-lām of the ism fāʿil and ism mafʿūl in the sense of الَّذِي and الَّتِي."},
  "ar": ["الْمَوْصُولَاتُ"], "notes": ["al-mawsul-wal-muarraf-bil-lam-wal-mudaf", "ism-mawsul"]},
 {"n": 70, "q": {"tr": "Atfın tarifi nedir? Atıf harfleri nelerdir? Zamîr-i merfû-i muttasıl ve mecrûr-i muttasıl üzerine atfın şartı nedir?", "en": "How is the conjunction defined, which are its letters, and on what condition is a word joined to an attached marfūʿ or majrūr pronoun?"},
  "a": {"tr": "Atıf: kendisi ile metbûu arasını on harften biri ayıran tâbidir. Harfleri: وَاو، فَاء، ثُمَّ، حَتَّى، أَوْ، إِمَّا، أَمْ، لَا، بَلْ، لَكِنْ. Merfû muttasıl zamir üzerine atıf murad olunduğunda, kelimenin bir cüz'ü gibi olan fâil üzerine atıf lâzım gelmesin diye önce munfasıl zamirle te'kidlenir (ضَرَبْتُ أَنَا وَزَيْدٌ). Mecrûr muttasıl üzerine atıfta, cârrın mecrûruna ittisali fâilin fiile ittisalinden kuvvetli olduğundan câr iade olunur (مَرَرْتُ بِكَ وَبِزَيْدٍ).", "en": "A follower between which and its antecedent one of ten letters stands: وَاو، فَاء، ثُمَّ، حَتَّى، أَوْ، إِمَّا، أَمْ، لَا، بَلْ، لَكِنْ. To join to an attached marfūʿ pronoun it is first confirmed by the detached one, lest the joining fall on a doer that is like a part of the word (ضَرَبْتُ أَنَا وَزَيْدٌ). To join to an attached majrūr pronoun the jarr letter is repeated, the letter's bond to its majrūr being stronger than the doer's to its verb (مَرَرْتُ بِكَ وَبِزَيْدٍ)."},
  "ar": ["تَابِعٌ يَتَوَسَّطُ بَيْنَهُ وَبَيْنَ مَتْبُوعِهِ أَحَدُ الْحُرُوفِ الْعَشَرَةِ", "ضَرَبْتُ أَنَا وَزَيْدٌ", "مَرَرْتُ بِكَ وَبِزَيْدٍ"], "notes": ["al-atf-bil-huruf-wa-ahkamuh", "atf-nasaq"]},
 {"n": 71, "q": {"tr": "Te'kid kaç kısımdır?", "en": "How many kinds of emphasis are there?"},
  "a": {"tr": "İki. Te'kid-i lafzî: birinci lafzın tekrarıyladır ve her lafızda cereyan eder — fiilde (ضَرَبَ ضَرَبَ زَيْدٌ عَمْرًا), isimde (جَاءَنِي زَيْدٌ زَيْدٌ), harfte (إِنَّ إِنَّ زَيْدًا قَائِمٌ), cümlede (زَيْدٌ قَائِمٌ زَيْدٌ قَائِمٌ). Te'kid-i mânevî: sayılı lafızlara mahsustur; dokuzdur: نَفْسُهُ، عَيْنُهُ، كِلَاهُمَا، كِلْتَاهُمَا، كُلُّهُ، أَجْمَعُ، أَكْتَعُ، أَبْتَعُ، أَبْصَعُ.", "en": "Two. Verbal emphasis: repeating the first word, in any word — a verb (ضَرَبَ ضَرَبَ زَيْدٌ عَمْرًا), a noun (جَاءَنِي زَيْدٌ زَيْدٌ), a particle (إِنَّ إِنَّ زَيْدًا قَائِمٌ), a sentence (زَيْدٌ قَائِمٌ زَيْدٌ قَائِمٌ). Semantic emphasis: confined to nine words — نَفْسُهُ، عَيْنُهُ، كِلَاهُمَا، كِلْتَاهُمَا، كُلُّهُ، أَجْمَعُ، أَكْتَعُ، أَبْتَعُ، أَبْصَعُ."},
  "ar": ["جَاءَنِي زَيْدٌ زَيْدٌ", "أَجْمَعُ"], "notes": ["al-tawkid-al-lafzi-wal-manawi", "tawkid"]},
 {"n": 72, "q": {"tr": "Bedelin tarifi nedir? Bedel kaç kısımdır?", "en": "How is the badal defined, and how many kinds has it?"},
  "a": {"tr": "Bedel: metbûu olmaksızın nisbetle kastolunandır. Dörttür: bedel-i kül mine'l-kül — medlûlleri bir olursa (جَاءَنِي زَيْدٌ أَخُوكَ); bedel-i ba'z mine'l-kül — bedel, mübdelün minhin bir cüz'ü olursa (ضَرَبْتُ زَيْدًا رَأْسَهُ); bedel-i iştimâl — aralarında külliyet ve cüz'iyyetin dışında bir alâka olursa (سُلِبَ زَيْدٌ ثَوْبَهُ); bedel-i galat — mübdelün minhin zikri galat olursa (رَأَيْتُ رَجُلًا حِمَارًا).", "en": "What is meant by the attribution, without its antecedent. Four: of the whole for the whole, when the two denote one thing (جَاءَنِي زَيْدٌ أَخُوكَ); of the part for the whole (ضَرَبْتُ زَيْدًا رَأْسَهُ); of inclusion, when some relation other than whole and part holds (سُلِبَ زَيْدٌ ثَوْبَهُ); of error, when the first was a slip (رَأَيْتُ رَجُلًا حِمَارًا)."},
  "ar": ["الْمَقْصُودُ بِالنِّسْبَةِ دُونَهُ", "ضَرَبْتُ زَيْدًا رَأْسَهُ", "سُلِبَ زَيْدٌ ثَوْبَهُ"], "notes": ["al-badal-wa-aqsamuh-wa-atf-al-bayan", "badal"]},
 {"n": 73, "q": {"tr": "Atf-ı beyânın tarifi nedir?", "en": "How is the explicative apposition defined?"},
  "a": {"tr": "Metbûunda bir mânâ ifade etmeyip metbûunu îzah için gelen tâbidir.", "en": "A follower brought to clarify its antecedent, indicating no meaning in it."},
  "ar": ["تَابِعٌ جِيءَ بِهِ لِإِيضَاحِ مَتْبُوعِهِ وَلَا يَدُلُّ عَلَى مَعْنًى فِيهِ"], "notes": ["al-badal-wa-aqsamuh-wa-atf-al-bayan", "atf-bayan"]},
]
